import LoginForm from "@/app/components/auth/LoginForm";

export default async function LoginPage({
  searchParams,
}: PageProps<"/auth/login">) {
  const nextPath = (await searchParams).next;
  const resolvedNextPath =
    typeof nextPath === "string" && nextPath.startsWith("/")
      ? nextPath
      : "/dashboard/workflow";

  return (
    <div className="space-y-8">
      <div className="space-y-3">
        <span className="inline-flex rounded-full bg-sky-100 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.18em] text-sky-700">
          Sign in
        </span>
        <h2 className="text-3xl font-semibold text-slate-950">
          Step back into your workflow studio.
        </h2>
        <p className="text-sm leading-6 text-slate-500">
          Use the demo account or your own mock credentials to enter the protected
          dashboard route at <span className="font-semibold text-slate-700">/dashboard/workflow</span>.
        </p>
      </div>

      <LoginForm nextPath={resolvedNextPath} />
    </div>
  );
}
